set-variable.value:
@{
      try {
        if (DateTime.UtcNow.Subtract((DateTime)context.Variables["inventoryStarted"]).TotalSeconds >= 5) { throw new Exception(); }
        var response = context.Variables["inventoryPage"] as IResponse;
        if (response == null || response.StatusCode != 200 || response.Body == null) { throw new Exception(); }
        var bytes = response.Body.As<byte[]>(preserveContent: true);
        if (bytes == null || bytes.Length > 1048576) { throw new Exception(); }
        var body = response.Body.As<string>();
        if (body == null || body.Length > 1048576 || Encoding.UTF8.GetByteCount(body) > 1048576) { throw new Exception(); }
        var page = JObject.Parse(body);
        var rows = page["value"] as JArray;
        var state = JObject.Parse((string)context.Variables["inventoryState"]);
        if (rows == null || (int)state["count"] + rows.Count > 1000) { throw new Exception(); }
        state["count"] = (int)state["count"] + rows.Count;
        var ids = (JArray)state["ids"];
        var seenIds = new HashSet<string>(ids.Select(id => (string)id), StringComparer.OrdinalIgnoreCase);
        var data = (JArray)state["data"];
        foreach (var token in rows) {
          var row = token as JObject;
          if (row == null || row["name"] == null || row["name"].Type != JTokenType.String || row["id"] == null || row["id"].Type != JTokenType.String || row["type"] == null || row["type"].Type != JTokenType.String) { throw new Exception(); }
          var name = (string)row["name"];
          if (!Regex.IsMatch(name, @"\A[A-Za-z0-9][A-Za-z0-9_.-]*\z") || !seenIds.Add(name) || !string.Equals((string)row["id"], (string)state["account"] + "/deployments/" + name, StringComparison.OrdinalIgnoreCase) || !string.Equals((string)row["type"], "Microsoft.CognitiveServices/accounts/deployments", StringComparison.OrdinalIgnoreCase)) { throw new Exception(); }
          ids.Add(name);
          var properties = row["properties"] as JObject;
          if (properties == null || properties["provisioningState"] == null || properties["provisioningState"].Type != JTokenType.String || string.IsNullOrWhiteSpace((string)properties["provisioningState"])) { throw new Exception(); }
          if (!string.Equals((string)properties["provisioningState"], "Succeeded", StringComparison.OrdinalIgnoreCase)) { continue; }
          var model = properties["model"] as JObject;
          if (model == null || model["name"] == null || model["name"].Type != JTokenType.String || string.IsNullOrWhiteSpace((string)model["name"])) { throw new Exception(); }
          var format = model["format"];
          var publisher = model["publisher"];
          if ((format != null && format.Type != JTokenType.Null && (format.Type != JTokenType.String || string.IsNullOrWhiteSpace((string)format))) || (publisher != null && publisher.Type != JTokenType.Null && (publisher.Type != JTokenType.String || string.IsNullOrWhiteSpace((string)publisher))) || (string.IsNullOrWhiteSpace((string)format) && string.IsNullOrWhiteSpace((string)publisher))) { throw new Exception(); }
          if (!string.Equals((string)format, "Anthropic", StringComparison.OrdinalIgnoreCase) && !string.Equals((string)publisher, "Anthropic", StringComparison.OrdinalIgnoreCase)) { continue; }
          var projected = new JObject(new JProperty("id", name), new JProperty("display_name", name));
          var family = Regex.Match((string)model["name"], @"\Aclaude-(?:[0-9]+(?:[.-][0-9]+)*-)?(opus|sonnet|haiku)(?:-|\z)", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant).Groups[1].Value.ToLowerInvariant();
          if (family != "") {
            projected["anthropic_family_tier"] = family;
            projected["is_family_default"] = name == (string)state["pins"][family];
          }
          data.Add(projected);
        }
        state["next"] = "";
        var nextToken = page["nextLink"];
        if (nextToken != null && nextToken.Type != JTokenType.Null) {
          if (nextToken.Type != JTokenType.String) { throw new Exception(); }
          var next = (string)nextToken;
          if (next != "") {
            if (next.Length > 8192 || next.Any(c => char.IsControl(c) || char.IsWhiteSpace(c)) || next.Contains("\\") || Regex.IsMatch(next, @"%(?![0-9a-fA-F]{2})")) { throw new Exception(); }
            var parts = Regex.Match(next, @"\Ahttps://management\.azure\.com(?::443)?(/[^?#]*)\?([^#]+)\z", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            if (!parts.Success || Regex.IsMatch(parts.Groups[1].Value, @"%(?:2f|5c|25)", RegexOptions.IgnoreCase) || !string.Equals(Uri.UnescapeDataString(parts.Groups[1].Value), (string)state["account"] + "/deployments", StringComparison.OrdinalIgnoreCase)) { throw new Exception(); }
            var query = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (var parameter in parts.Groups[2].Value.Split('&')) {
              var separator = parameter.IndexOf('=');
              if (separator < 1) { throw new Exception(); }
              var key = System.Net.WebUtility.UrlDecode(parameter.Substring(0, separator));
              var value = System.Net.WebUtility.UrlDecode(parameter.Substring(separator + 1));
              if ((key != "api-version" && !string.Equals(key, "$skiptoken", StringComparison.OrdinalIgnoreCase)) || query.ContainsKey(key) || value.Length == 0 || value.Any(c => char.IsControl(c)) || parameter.Contains(";")) { throw new Exception(); }
              query.Add(key, value);
            }
            if (query.Count != 2 || !query.ContainsKey("api-version") || query["api-version"] != "2024-10-01" || !query.ContainsKey("$skiptoken")) { throw new Exception(); }
            var seen = (JArray)state["seen"];
            if (seen.Any(value => (string)value == query["$skiptoken"])) { throw new Exception(); }
            seen.Add(query["$skiptoken"]);
            state["next"] = "https://management.azure.com" + (string)state["path"] + "?" + parts.Groups[2].Value;
          }
        }
        return state.ToString(Newtonsoft.Json.Formatting.None);
      } catch { throw new Exception("Model inventory unavailable."); }
    }
